#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    int current_floor = 0; // elevator starts at floor 0
    for (int i = 1; i < argc; ++i) {
        char *endptr = NULL;
        long target_long = strtol(argv[i], &endptr, 10);
        // Validate: must be a non‑negative integer within 0‑9 and fully consumed
        if (endptr == argv[i] || *endptr != '\0' || target_long < 0 || target_long > 9) {
            puts("INVALID_FLOOR");
            continue;
        }
        int target = (int)target_long;
        // Move floor‑by‑floor until we reach the target
        while (current_floor != target) {
            if (current_floor < target) {
                printf("MOVE_UP %d->%d\n", current_floor, current_floor + 1);
                ++current_floor;
            } else {
                printf("MOVE_DOWN %d->%d\n", current_floor, current_floor - 1);
                --current_floor;
            }
        }
        // Arrival actions
        printf("ARRIVE %d\n", current_floor);
        puts("DOORS_OPEN");
        puts("DOORS_CLOSE");
    }
    printf("FINAL_FLOOR=%d\n", current_floor);
    return 0;
}
